// CASE-356: built runtime, local Worker/Auth only. No deployed origin or metered backend.
import {test,expect} from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import {startLocalAuthStub} from '../tests/helpers/local-auth-stub.mjs';
import {startPublishedWorker} from '../tests/helpers/published-worker.mjs';
import {startServedAuthShell} from '../tests/helpers/served-auth-shell.mjs';
import {startAdminShell} from '../tests/helpers/admin-shell.mjs';
import {uuidv7} from '../src/shared/ids.mjs';
import {caseVersionUrl,sessionsUrl,sessionRecordUrl} from '../src/shared/urls.mjs';
import {settled} from '../tests/helpers/settled.mjs';
import {chooseOption} from '../tests/helpers/choose-option.mjs';
let auth,worker,shell;
test.beforeAll(async()=>{auth=await startLocalAuthStub({appOrigin:null,jwt:null});worker=await startPublishedWorker({authOrigin:auth.origin,secondVersion:true});auth.setJwt(worker.jwt);shell=await startServedAuthShell({apiOrigin:worker.origin,buildAuthBindings:{SUPABASE_URL:auth.origin,SUPABASE_JWT_ISSUER:auth.origin+'/auth/v1',SUPABASE_JWKS_URL:auth.origin+'/auth/v1/.well-known/jwks.json'}});auth.setAppOrigin(shell.origin);});
test.afterAll(async()=>{await shell?.stop();await worker?.stop();await auth?.stop();});
async function signIn(page,url=shell.origin+'/present'){await page.goto(url);await page.getByLabel('Email',{exact:true}).fill('owner@example.invalid');await page.getByRole('button',{name:'Email me a sign-in code',exact:true}).click();await page.getByLabel('One-time code').fill('123456');await page.getByRole('button',{name:'Sign in',exact:true}).click();await expect(page.locator('.library-list')).toBeVisible();}
async function axe(page){await settled(page);const v=(await new AxeBuilder({page}).analyze()).violations;expect(v.map(x=>x.id+' '+x.nodes.map(n=>n.target.join(' ')).join(','))).toEqual([]);const reflow=await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,breadcrumb:document.querySelector('.site-breadcrumbs')?.textContent,overflow:[...document.querySelectorAll('body *')].filter(n=>{const r=n.getBoundingClientRect();return r.width&&r.right>innerWidth+1;}).slice(0,8).map(n=>({tag:n.tagName,cls:String(n.className),text:n.textContent?.slice(0,60),width:n.getBoundingClientRect().width}))}));expect(reflow.scroll,JSON.stringify(reflow)).toBeLessThanOrEqual(reflow.width+1);const tops=await page.locator('.site-breadcrumbs>.site-context').evaluateAll(ns=>ns.map(n=>n.getBoundingClientRect().top));if(tops.length>1)expect(Math.max(...tops)-Math.min(...tops)).toBeLessThanOrEqual(1);}
test('public Join stays idle; menu Settings expands in place for signed-out and recovered accounts',async({browser})=>{
 for(const kept of [false,true]){const ctx=await browser.newContext({ignoreHTTPSErrors:true,viewport:{width:390,height:844}});try{if(kept)await ctx.addInitScript(()=>localStorage.setItem('case:auth:refresh','local-refresh-only'));const page=await ctx.newPage(),calls=[];page.on('request',r=>{if(new URL(r.url()).pathname.startsWith('/api/')||new URL(r.url()).origin===auth.origin)calls.push(r.url());});await page.goto(shell.origin+'/');await expect(page.getByRole('heading',{name:'Join the Case',exact:true})).toBeVisible();await page.waitForTimeout(150);expect(calls.filter(u=>new URL(u).pathname!=='/api/v1/config')).toEqual([]);
 await page.getByRole('button',{name:'Open menu'}).click();const menu=page.getByRole('dialog',{name:'Menu'});await expect(menu.getByRole('link',{name:kept?'Present':'Sign in',exact:true})).toBeVisible();await expect(menu.getByRole('link',{name:'Join',exact:true})).toBeVisible();const settings=menu.getByRole('button',{name:'Settings',exact:true});await settings.click();await expect(settings).toHaveAttribute('aria-expanded','true');await expect(menu.getByRole('region',{name:'Device settings'})).toBeVisible();await expect(menu.getByRole('group',{name:'Sound',exact:true}).getByRole('button',{name:'Music',exact:true})).toBeVisible();await expect(menu.getByRole('switch',{name:'Reduce motion',exact:true})).toBeVisible();await expect(page.getByRole('dialog')).toHaveCount(1);await axe(page);await settings.click();await expect(settings).toHaveAttribute('aria-expanded','false');await page.keyboard.press('Escape');await expect(page.getByRole('button',{name:'Open menu'})).toBeFocused();}finally{await ctx.close();}}
});
test('Present has bounded neighbour navigation, readable responsive preparation, scoped Sessions and compatible bookmarks',async({browser})=>{
 const ctx=await browser.newContext({ignoreHTTPSErrors:true,viewport:{width:1440,height:1000}});try{const page=await ctx.newPage();await signIn(page,shell.origin+'/cases');await expect(page).toHaveURL(shell.origin+'/present');await expect(page.getByRole('navigation',{name:'Case collection'})).toHaveCount(0);expect(await page.locator('.library-list .case-card-body').first().evaluate(n=>getComputedStyle(n).padding)).toBe('24px');await page.getByRole('link',{name:'Published case',exact:true}).click();await expect(page.getByRole('heading',{name:'Present this case',exact:true})).toBeVisible();const artBox=await page.locator('.case-identity').boundingBox();expect(artBox.width/artBox.height).toBeCloseTo(16/9,2);await expect(page.getByRole('link',{name:'Check active sessions',exact:true})).toHaveCount(0);await expect(page.getByRole('link',{name:'Sessions',exact:true})).toHaveAttribute('href',sessionsUrl(shell.origin,worker.workspaceId,worker.caseId));await expect(page.locator('.case-record')).toContainText('Not recorded');const actions=page.locator('.case-present-tools > .btn,.case-present-tools > .surface-disclosure > .btn,.case-present-foot > .btn');await expect(actions).toHaveCount(4);const geometry=await actions.evaluateAll(ns=>ns.map(n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);return {width:r.width,height:r.height,radius:s.borderRadius,padding:s.padding};}));expect(new Set(geometry.map(x=>JSON.stringify(x))).size).toBe(1);expect(geometry[0].height).toBe(52);await expect(page.getByRole('button',{name:'Present',exact:true})).toBeVisible();expect(await page.locator('.case-record .btn').evaluateAll(ns=>ns.every(n=>getComputedStyle(n).backgroundColor==='rgba(0, 0, 0, 0)'&&getComputedStyle(n).padding==='0px'))).toBe(true);const forward=await page.getByRole('button',{name:'Next',exact:true}).isEnabled()?'Next':'Previous';let releaseCase,caseRequested;const heldCase=new Promise(r=>releaseCase=r),caseRead=new Promise(r=>caseRequested=r);await page.route('**/api/v1/cases/*/versions/*',async route=>{caseRequested();await heldCase;await route.continue();},{times:1});await page.getByRole('button',{name:forward,exact:true}).click();await caseRead;await expect(page.getByRole('heading',{level:1,name:'Published case',exact:true})).toBeVisible();await expect(page.locator('.case-detail[aria-busy=true]')).toHaveCount(1);expect(await page.locator('.case-detail[aria-busy=true]').evaluate(n=>n.inert)).toBe(true);releaseCase();await expect(page.getByRole('heading',{level:1,name:'Other published case'})).toBeVisible();await expect(page.getByRole('heading',{level:1,name:'Published case',exact:true})).toHaveCount(0);await page.getByRole('button',{name:forward==='Next'?'Previous':'Next',exact:true}).click();await expect(page).toHaveURL(caseVersionUrl(worker.caseId,1,shell.origin));
 for(const width of [1440,912,390,320])for(const theme of ['light','dark']){await page.setViewportSize({width,height:1000});await page.evaluate(t=>document.documentElement.dataset.theme=t,theme);await axe(page);if(width<720){const boxes=await page.locator('.case-identity,.case-overview,.case-present,.case-record').evaluateAll(ns=>Object.fromEntries(ns.map(n=>[n.classList.contains('case-identity')?'identity':n.classList.contains('case-overview')?'overview':n.classList.contains('case-present')?'present':'record',n.getBoundingClientRect().top])));expect(boxes.identity).toBeLessThan(boxes.overview);expect(boxes.overview).toBeLessThan(boxes.present);expect(boxes.present).toBeLessThan(boxes.record);}}
 await page.emulateMedia({reducedMotion:'reduce'});await page.evaluate(()=>document.documentElement.style.fontSize='200%');await page.setViewportSize({width:320,height:1000});const [previewBox,presentBox]=await page.locator('.case-present-foot > .btn').evaluateAll(ns=>ns.map(n=>{const r=n.getBoundingClientRect();return {left:r.left,right:r.right};}));expect(previewBox.right).toBeLessThanOrEqual(presentBox.left);expect(await page.locator('.case-present-tools button,.case-present-tools a,.case-present-foot button').evaluateAll(buttons=>buttons.flatMap(button=>{const walker=document.createTreeWalker(button,NodeFilter.SHOW_TEXT),bad=[];let node;while(node=walker.nextNode())for(const match of node.textContent.matchAll(/\S+/g)){const range=document.createRange();range.setStart(node,match.index);range.setEnd(node,match.index+match[0].length);if(new Set([...range.getClientRects()].map(r=>Math.round(r.top))).size>1)bad.push(match[0]);}return bad;}))).toEqual([]);await axe(page);await page.screenshot({path:'/tmp/case-runtime-views/detail-large-text.png',fullPage:true});await page.evaluate(()=>document.documentElement.style.fontSize='');await page.setViewportSize({width:912,height:1000});const version=page.locator('.case-record').getByRole('button',{name:/v1/});await version.click();await expect(page.getByRole('dialog',{name:'Versions'})).toBeVisible();await page.keyboard.press('Escape');await expect(version).toBeFocused();
 }finally{await ctx.close();}
});
test('Account has profile/access only; Sessions deep records use authorised readers without claiming a live room',async({browser})=>{
 const ctx=await browser.newContext({ignoreHTTPSErrors:true,viewport:{width:390,height:900}});try{const page=await ctx.newPage();await signIn(page);const calls=[];page.on('request',r=>{if(new URL(r.url()).pathname.startsWith('/api/'))calls.push(new URL(r.url()).pathname);});await page.goto(shell.origin+'/account');await expect(page.getByRole('heading',{name:'Your profile'})).toBeVisible();await expect(page.getByRole('heading',{name:'Your access'})).toBeVisible();await axe(page);expect(calls.some(p=>p.includes('/portfolio/')||p.includes('/claim'))).toBe(false);await page.screenshot({path:'/tmp/case-runtime-views/account.png',fullPage:true});
 const name=page.getByLabel('Name',{exact:true});await name.fill('Unsaved profile');await page.getByRole('button',{name:'Open menu'}).click();await page.getByRole('dialog',{name:'Menu'}).getByRole('link',{name:'Sessions',exact:true}).click();const discard=page.getByRole('dialog',{name:'Discard changes?',exact:true});await expect(discard).toBeVisible();await discard.getByRole('button',{name:'Keep editing'}).click();await expect(name).toHaveValue('Unsaved profile');await page.getByRole('button',{name:'Open menu'}).click();await page.getByRole('dialog',{name:'Menu'}).getByRole('link',{name:'Sessions',exact:true}).click();await page.getByRole('dialog',{name:'Discard changes?',exact:true}).getByRole('button',{name:'Discard changes',exact:true}).click();await expect(page).toHaveURL(shell.origin+'/sessions');
 const record=uuidv7();let read=0;await page.route('**/api/v1/portfolio/record',async r=>{expect(r.request().postDataJSON().sessionId).toBe(record);read++;await r.fulfill({status:403,json:{error:'forbidden'}});});await page.goto(sessionRecordUrl(record,shell.origin));await expect.poll(()=>read).toBe(1);await expect(page.locator('.session-detail')).toContainText(/access|unavailable|permitted/i);expect(calls.some(p=>p.includes('/claim'))).toBe(false);
 await page.goto(shell.origin+'/history');await expect(page).toHaveURL(shell.origin+'/sessions');await expect(page.getByRole('heading',{level:1,name:'Sessions'})).toHaveCount(1);
 }finally{await ctx.close();}
});
