 await page.getByRole('button',{name:'+ Invite person',exact:true}).click();const invite=page.getByRole('dialog',{name:'Invite person'});await invite.getByLabel('Email address',{exact:true}).fill('kept@example.invalid');await invite.getByRole('button',{name:'Show full permissions',exact:true}).click();await expect(invite.locator('.permission-row')).toHaveCount(49);await expect(invite.locator('.permission-cell')).toHaveCount(441);for(const [action,principal,value]of [['P-47','participant','cap'],['P-48','admin','yes'],['P-48','owner','no'],['P-49','admin','cap']])await expect(invite.locator('.permission-row[data-action='+action+'] .permission-cell[data-principal='+principal+']')).toHaveAttribute('data-permission',value);await chooseOption(invite.getByRole('combobox',{name:'Permission comparison scope'}),'Case-only access');for(const width of [912,390,320])for(const theme of ['light','dark']){await page.setViewportSize({width,height:1000});await page.evaluate(t=>document.documentElement.dataset.theme=t,theme);await axe(page);}
 await invite.getByRole('button',{name:'Cancel',exact:true}).click();const discard=page.getByRole('dialog',{name:'Discard changes?',exact:true});await expect(discard.getByRole('button',{name:'Keep editing'})).toBeFocused();await page.mouse.click(4,4);await expect(discard).toBeHidden();await expect(invite.getByLabel('Email address',{exact:true})).toHaveValue('kept@example.invalid');await invite.getByRole('button',{name:'Cancel',exact:true}).click();await expect(discard).toBeVisible();await discard.getByRole('button',{name:'Keep editing'}).click();await expect(invite.getByLabel('Email address',{exact:true})).toHaveValue('kept@example.invalid');await expect(invite.getByRole('combobox',{name:'Access',exact:true})).toContainText('Can run');
