test('Settings Music auditions all shipped tracks and a local countdown without live writes or changing the console timer pick',async({browser})=>{
 test.setTimeout(60000);
 const ctx=await browser.newContext({ignoreHTTPSErrors:true,viewport:{width:390,height:1000},reducedMotion:'no-preference'});try{
 await ctx.addInitScript(()=>{localStorage.setItem('case:console:timer-seconds','150');window.audioProof={created:0,decoded:0,started:0,closed:0};const Native=window.AudioContext;window.AudioContext=class extends Native{constructor(...args){super(...args);window.audioProof.created++;}decodeAudioData(...args){window.audioProof.decoded++;return super.decodeAudioData(...args);}createBufferSource(){const source=super.createBufferSource(),start=source.start.bind(source);source.start=(...args)=>{window.audioProof.started++;return start(...args);};return source;}close(){window.audioProof.closed++;return super.close();}};});
 const page=await ctx.newPage(),writes=[];page.on('request',r=>{if(r.method()==='POST'&&new URL(r.url()).pathname.startsWith('/api/'))writes.push(new URL(r.url()).pathname);});await page.goto(shell.origin+'/');await page.getByRole('button',{name:'Open menu'}).click();await page.getByRole('button',{name:'Settings',exact:true}).click();const music=page.getByRole('button',{name:'Music',exact:true});const menu=page.getByRole('dialog',{name:'Menu',exact:true});await expect(menu.locator('.site-menu-notice')).toHaveText('');const before=await menu.boundingBox();await page.evaluate(()=>{document.querySelectorAll('link[rel=stylesheet]').forEach(n=>{if(/\/console\.[a-f0-9]{64}\.css$/.test(n.href))n.remove();});let failed=false;const append=document.head.append.bind(document.head);document.head.append=(...nodes)=>{const link=nodes.find(n=>n.tagName==='LINK'&&/\/console\.[a-f0-9]{64}\.css$/.test(n.href));if(link&&!failed){failed=true;link.dispatchEvent(new Event('error'));return;}append(...nodes);};});await music.click();await expect(page.locator('.surface-toast')).toContainText('Music is unavailable. Try again.');await expect(music).toBeEnabled();await expect(menu.locator('.site-menu-notice')).toHaveText('');const after=await menu.boundingBox();expect(after.height).toBe(before.height);await music.click();await expect(page.locator('.surface-toast:visible')).toHaveCount(0);const dialog=page.getByRole('dialog',{name:'Music',exact:true});await expect(dialog).toBeVisible();expect(await page.evaluate(()=>window.audioProof.created)).toBe(0);await expect(dialog.getByRole('group',{name:'All tracks'}).getByRole('button')).toHaveCount(7);
 await dialog.getByRole('button',{name:'Longer timer',exact:true}).click();await dialog.getByRole('button',{name:'Start 1:45',exact:true}).click();await expect(dialog.locator('[data-timer-clock]')).toHaveText(/1:4/);expect(await page.evaluate(()=>localStorage.getItem('case:console:timer-seconds'))).toBe('150');
 await dialog.getByRole('button',{name:'Play audition',exact:true}).click();await expect.poll(()=>page.evaluate(()=>window.audioProof.started),{timeout:15000}).toBeGreaterThan(0);expect(await page.evaluate(()=>window.audioProof.decoded)).toBeGreaterThan(0);
 for(const name of ['Atlas · Current','Atlas · Crossing','Side Street','Night Platform','Atlas · Arrival','Side Street · Afterglow']){const previous=await dialog.locator('.player-title').textContent(),before=await page.evaluate(()=>window.audioProof.started);await dialog.getByRole('button',{name,exact:true}).click();await expect(dialog.locator('.player-title')).toHaveText(name);if(previous!==name)await expect.poll(()=>page.evaluate(()=>window.audioProof.started),{timeout:15000}).toBeGreaterThan(before);}
 for(const width of [320,390,912])for(const theme of ['light','dark']){await page.setViewportSize({width,height:1000});await page.evaluate(t=>document.documentElement.dataset.theme=t,theme);await axe(page);}
 await dialog.getByRole('button',{name:'Close music'}).click();await expect(dialog).toBeHidden();await expect(music).toBeFocused();expect(await page.evaluate(()=>window.audioProof.closed)).toBe(1);expect(await page.evaluate(()=>localStorage.getItem('case:console:timer-seconds'))).toBe('150');expect(writes).toEqual([]);
 }finally{await ctx.close();}
});


test('draft cards use verified facts without empty covers and remain usable on narrow screens', async ({ browser }) => {
  const previous = worker.fake.replies.get('builder_list_draft_summaries');
  const summary={audience:'Registrars',duration_min:30,art_structure:{v:1,stops:2,decisions:[{stop:0,strands:[],resets:1,ends:0}]},publication_version:2,publication_at:'2026-10-18T00:00:00Z',publication_state:'changed',review_status:'pending'};
  worker.fake.replies.set('builder_list_draft_summaries', [
    { ...summary,case_id: worker.caseId, title: 'A long saved case title that must wrap fully without pushing its saved facts outside the card', revision: 9007199254740991, updated_at: '2026-11-02T08:05:00.000Z' },
    { ...summary,art_structure:null,publication_version:null,publication_at:null,publication_state:'none',review_status:null,case_id: worker.secondVersionId, title: 'Short draft', revision: 0, updated_at: '2026-10-19T13:03:00.000Z' },
  ]);
  const ctx = await browser.newContext({ ignoreHTTPSErrors: true, locale: 'en-AU', timezoneId: 'Australia/Perth' });
  try {
    const page = await ctx.newPage(), caseReads = [];
    page.on('request', request => { if (new URL(request.url()).pathname.includes('/builder/cases/')) caseReads.push(request.url()); });
    await signIn(page); await page.goto(shell.origin + '/create');
    const cards = page.locator('.builder-saved-drafts .case-tile'); await expect(cards).toHaveCount(2);await expect(page.getByRole('button',{name:'Share workspace',exact:true})).toBeHidden();await expect(page.getByRole('button',{name:'Groups',exact:true})).toBeHidden();
    await expect(cards.locator('.cover')).toHaveCount(2);await expect.poll(()=>cards.locator('canvas').first().evaluate(n=>n.width)).toBeGreaterThan(1);
    await expect(cards.first()).toContainText('30 min');await expect(cards.first()).toContainText('Unpublished changes · v2');await expect(cards.first()).toContainText('In review');expect((await cards.first().getByText('In review',{exact:true}).boundingBox()).height).toBeLessThan(30);await expect(cards.last()).toContainText('No current review');
    await expect(cards.last().locator('time')).toHaveAttribute('datetime', '2026-10-19T13:03:00.000Z');
    for (const [width, height] of [[320,568],[390,844],[768,1024],[1366,900],[844,390]]) for (const theme of ['light','dark']) {
      await page.setViewportSize({ width, height }); await page.evaluate(t => document.documentElement.dataset.theme = t, theme);
      await axe(page);
      const short = await cards.last().boundingBox();
      if(width<720){const artwork=await cards.last().locator('.cover').boundingBox();expect(short.height-artwork.height).toBeLessThan(260);expect(artwork.width/artwork.height).toBeCloseTo(1.6,1);}else expect(Math.abs(short.height-(await cards.first().boundingBox()).height)).toBeLessThanOrEqual(1);
      for (const card of await cards.all()) {
        expect(await card.getByRole('button').count()).toBe(1);
        expect(await card.locator('dl dt').allTextContents()).toEqual(['Saved', 'Revision']);
        const overflow = await card.evaluate(n => [...n.querySelectorAll('h2,dt,dd,time')].some(e => e.scrollWidth > e.clientWidth + 1));
        expect(overflow).toBe(false);
      }
      if (width < 720) expect(await cards.first().locator('.case-card-body').evaluate(n => getComputedStyle(n).padding)).toBe('16px');
      const open = cards.last().getByRole('button'); await open.focus(); await page.keyboard.press('Enter');
      const modal = page.getByRole('dialog', { name: 'Short draft', exact: true }); await expect(modal).toBeVisible();
      const edit = modal.getByRole('button', { name: 'Edit case', exact: true }); await edit.scrollIntoViewIfNeeded(); await expect(edit).toBeInViewport();
      await modal.getByRole('button', { name: 'Cancel', exact: true }).click(); await expect(open).toBeFocused();
    }
    await page.setViewportSize({width:320,height:568});
    await cards.evaluateAll(nodes => { for (const node of nodes) for (const e of node.querySelectorAll('h2,.case-meta,dt,dd')) e.style.fontSize = (parseFloat(getComputedStyle(e).fontSize) * 2) + 'px'; });
    await axe(page); expect(caseReads).toEqual([]);
  } finally {
    await ctx.close(); if (previous === undefined) worker.fake.replies.delete('builder_list_draft_summaries'); else worker.fake.replies.set('builder_list_draft_summaries', previous);
  }
});


