  await page.goBack();await expect(page.locator('.library-drafts')).toBeVisible();await page.goForward();await expect(page.locator('.portfolio')).toBeVisible();expect(await page.evaluate(()=>window.caseDocumentMarker)).toBe(marker);await axe(page);
